body.script:
//
					const cfg     = document.getElementById('cfg').dataset;
					const ASSET   = cfg.asset;
					const REFRESH = parseInt(cfg.refresh, 10) * 1000;
					let nextRefreshAt = Date.now() + REFRESH;
					let INTERVAL = '1h';

					const klineUrl = (iv, limit) => '/api/klines/' + ASSET + '?interval=' + iv + '&limit=' + limit;

					let EXPIRY_VALUE = '0';
					let WINDOW_VALUE = 'all';
					const dhsUrl = () => {
						const expiryPart = EXPIRY_VALUE === 'all' ? 'expiry=all' : 'expiry_index=' + EXPIRY_VALUE;
						return '/api/dealer-hedging/' + ASSET + '?' + expiryPart + '&hours=' + WINDOW_VALUE;
					};

					function onExpiryChange() {
						EXPIRY_VALUE = document.getElementById('expiry-select').value;
						refreshDealerHedging();
					}
					function onWindowChange() {
						WINDOW_VALUE = document.getElementById('window-select').value;
						refreshDealerHedging();
					}

					const tzOffset = (() => {
						let zone;
						try { zone = Intl.DateTimeFormat().resolvedOptions().timeZone; }
						catch (e) { return 0; }
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }
					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => chart.resize(window.innerWidth, window.innerHeight));
					function repositionBelowToolbar() {
						const bar = document.getElementById('tf-bar');
						if (!bar) return;
						const bottom = Math.ceil(bar.getBoundingClientRect().bottom);
						document.documentElement.style.setProperty('--tf-bar-bottom', bottom + 'px');
					}
					window.addEventListener('resize', repositionBelowToolbar);
					repositionBelowToolbar();

					// Keeps #dhs-panel clear of the chart's own right price
					// scale, whose width varies with price digit count (and
					// can shift as new price lines/candles change which
					// labels are widest) — read the scale's own current width
					// rather than assuming a fixed value. #dhs-forecast-box
					// lives at top-left now, so it needs no right-edge
					// clearance (and must NOT get a `right` style set here —
					// combined with its own `left`, that would stretch it to
					// fill the gap between the two instead of keeping its own
					// max-width).
					function repositionRightBoxes() {
						const scaleWidth = chart.priceScale('right').width() || 70;
						['dhs-panel'].forEach(id => {
							const el = document.getElementById(id);
							if (el) el.style.right = (scaleWidth + 12) + 'px';
						});
					}
					window.addEventListener('resize', repositionRightBoxes);
					repositionRightBoxes();

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// Simulated dealer-hedging-pressure forward path — a distinct
					// light-violet palette so it's never confused with the real
					// candles above or with the (unrelated) Thales Forecast
					// engine's own light green/red on the Delta Chart.
					const forecastSeries = chart.addCandlestickSeries({
						upColor: '#b39ddb', downColor: '#d1a3d8',
						borderVisible: true, borderUpColor: '#7e57c2', borderDownColor: '#8e24aa',
						wickUpColor: '#7e57c2', wickDownColor: '#8e24aa',
						priceLineVisible: false, lastValueVisible: false,
					});

					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					let flipLine = null;
					let wallLines = [];
					function clearOverlayLines() {
						if (flipLine) { series.removePriceLine(flipLine); flipLine = null; }
						wallLines.forEach(l => series.removePriceLine(l));
						wallLines = [];
					}

					let SHOW_WALLS = true;
					let SHOW_FORECAST = true;
					function onToggleWalls() {
						SHOW_WALLS = document.getElementById('walls-toggle').checked;
						renderOverlays(lastData);
					}
					function onToggleForecast() {
						SHOW_FORECAST = document.getElementById('forecast-toggle').checked;
						renderForecast(lastData);
						document.getElementById('dhs-forecast-box').style.display = SHOW_FORECAST ? 'block' : 'none';
					}

					function formatAbbreviated(value) {
						const sign = value < 0 ? '-' : '';
						const abs = Math.abs(value);
						if (abs >= 1e6) return sign + Math.round(abs / 1e6).toLocaleString('en-US') + 'M';
						if (abs >= 1e3) return sign + Math.round(abs / 1e3).toLocaleString('en-US') + 'K';
						return sign + Math.round(abs).toLocaleString('en-US');
					}

					let lastData = null;

					function renderOverlays(data) {
						clearOverlayLines();
						if (!data) return;
						if (data.gamma_flip_price) {
							flipLine = series.createPriceLine({
								price: data.gamma_flip_price, color: '#ff9800', lineWidth: 2,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: '#ff9800', title: 'Gamma Flip',
							});
						}
						if (SHOW_WALLS && data.gamma_walls) {
							data.gamma_walls.slice(0, 6).forEach(w => {
								const color = w.dealer_gamma > 0 ? '#2e7d32' : '#c62828';
								wallLines.push(series.createPriceLine({
									price: w.strike, color: color, lineWidth: 1,
									lineStyle: LightweightCharts.LineStyle.Dotted,
									axisLabelVisible: true, axisLabelColor: color,
									title: 'Wall ' + formatAbbreviated(w.dealer_gamma),
								}));
							});
						}
					}

					function renderForecast(data) {
						if (!SHOW_FORECAST || !data || !data.simulation || !realCandles.length) {
							forecastSeries.setData([]);
							return;
						}
						// The simulator always steps hourly regardless of the
						// chart's own selected Timeframe (4h/1d candles just
						// show these 24 hourly forecast bars compressed
						// together near "now" — a deliberate near-term view,
						// not resampled to match the main series' own grid).
						const lastTime = realCandles[realCandles.length - 1].time;
						const candles = data.simulation.candles.map(c => ({
							time: lastTime + Math.round(c.hours * 3600),
							open: c.open, high: c.high, low: c.low, close: c.close,
						}));
						forecastSeries.setData(candles);
					}

					function regimeLabel(regime) {
						if (regime === 'long_gamma') return '<span class="regime-long">LONG GAMMA (pin/damp)</span>';
						if (regime === 'short_gamma') return '<span class="regime-short">SHORT GAMMA (amplify)</span>';
						return '<span class="regime-neutral">NEUTRAL</span>';
					}

					function renderPanel(data) {
						const panel = document.getElementById('dhs-panel');
						if (!data || !data.index_price) {
							panel.textContent = ASSET + ' Dealer Hedging Simulator\n(no active expiry / no trades in window yet)';
							return;
						}
						const flip = data.gamma_flip_price ? '$' + Math.round(data.gamma_flip_price).toLocaleString('en-US') : 'n/a';
						const scope = data.instrument || (ASSET + ' (all expiries)');
						const windowLabel = data.window_hours === 'all' ? 'full position'
							: data.window_hours === 'midnight' ? 'since 00:00 UTC'
							: data.window_hours + 'h trailing';
						panel.innerHTML =
							ASSET + ' Dealer Hedging Simulator\n' +
							'Scope:        ' + scope + '  (' + windowLabel + ')\n' +
							'Index Price:  $' + Math.round(data.index_price).toLocaleString('en-US') + '\n' +
							'Regime:       ' + regimeLabel(data.regime) + '\n' +
							'Dealer Gamma: ' + formatAbbreviated(data.dealer_gamma_at_spot) + '\n' +
							'Dealer Delta: ' + formatAbbreviated(data.dealer_delta_at_spot) + '\n' +
							'Gamma Flip:   ' + flip + '\n' +
							'Trades:       ' + data.trade_count;
					}

					// Plain-English summary of what simulate_hedging_path()
					// (server-side, dealer_hedging.py) actually produced —
					// direction/magnitude of the simulated path, WHY (the
					// regime), and the nearest wall for context. Computed
					// client-side from the same response renderPanel() reads,
					// not a separate server call.
					function buildForecastExplanation(data) {
						if (!data || !data.index_price) {
							return 'No forecast — no active expiry or no trades in the selected window.';
						}
						if (!data.simulation || !data.simulation.candles || !data.simulation.candles.length) {
							return 'No forecast candles for this scope/window.';
						}
						const candles = data.simulation.candles;
						const open0 = candles[0].open;
						const closeN = candles[candles.length - 1].close;
						const pct = (closeN - open0) / open0 * 100;
						const hours = data.simulation.hours_ahead;
						const dir = pct > 0.02 ? 'UP' : pct < -0.02 ? 'DOWN' : 'ROUGHLY FLAT';

						const regimeText = data.regime === 'short_gamma'
							? 'dealers are short gamma, so moves tend to get amplified'
							: data.regime === 'long_gamma'
							? 'dealers are long gamma, so moves tend to get damped/pinned'
							: 'dealer gamma is roughly flat — no strong pin or amplification bias';

						let wallLine = '';
						if (data.gamma_walls && data.gamma_walls.length) {
							const nearest = data.gamma_walls.slice().sort((a, b) =>
								Math.abs(a.strike - data.index_price) - Math.abs(b.strike - data.index_price))[0];
							const side = nearest.strike >= data.index_price ? 'above' : 'below';
							const kind = nearest.dealer_gamma > 0 ? 'a pin (dealer long gamma)' : 'an acceleration level (dealer short gamma)';
							wallLine = '\nNearest wall: $' + Math.round(nearest.strike).toLocaleString('en-US') + ' (' + side + ' spot) — ' + kind + '.';
						}

						return 'Predicted: ' + dir + ' ~' + (pct >= 0 ? '+' : '') + pct.toFixed(2) + '% over ' + hours + 'h'
							+ ' ($' + Math.round(open0).toLocaleString('en-US') + ' → $' + Math.round(closeN).toLocaleString('en-US') + ').\n'
							+ data.regime.replace('_', ' ').toUpperCase() + ' regime — ' + regimeText + '.'
							+ wallLine;
					}

					function renderForecastBox(data) {
						const box = document.getElementById('dhs-forecast-box');
						if (!box) return;
						box.innerHTML = buildForecastExplanation(data)
							+ '\n<span class="caveat">Dealer-hedging pressure only — a heuristic, not a price guarantee.</span>';
					}

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function showSpinner() { document.getElementById('spinner').style.display = 'block'; }
					function hideSpinner() { document.getElementById('spinner').style.display = 'none'; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					let realCandles = [];

					const TF_WINDOW = { '1h': 15, '4h': 30, '1d': 365 };
					const INTERVAL_SECONDS = { '1h': 3600, '4h': 4 * 3600, '1d': 86400 };
					const FUTURE_MARGIN_DAYS = 5;

					function applyVisibleRange() {
						if (!realCandles.length) return;
						const days = TF_WINDOW[INTERVAL] || 15;
						const futureEdge = realCandles[realCandles.length - 1].time + FUTURE_MARGIN_DAYS * 86400;
						chart.timeScale().setVisibleRange({ from: futureEdge - days * 86400, to: futureEdge });
					}

					function rebuildSeriesData() {
						series.setData(realCandles);
						const intervalSec = INTERVAL_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = Math.round(FUTURE_MARGIN_DAYS * 86400 / intervalSec);
						const futureTicks = [];
						for (let i = 1; i <= count; i++) futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						futureAxisSeries.setData(futureTicks);
					}

					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					const contextMenu = document.getElementById('context-menu');
					function hideContextMenu() { contextMenu.style.display = 'none'; }
					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}
					function onResetChartViewClick() { resetChartView(); hideContextMenu(); }

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => { e.preventDefault(); showContextMenu(e.clientX, e.clientY); });
					document.addEventListener('contextmenu', e => { if (!chartContainerEl.contains(e.target)) hideContextMenu(); });
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					async function loadCandles() {
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						rebuildSeriesData();
						applyVisibleRange();
						renderForecast(lastData);
						repositionRightBoxes();
					}

					async function updateLatestCandle() {
						const resp = await (await fetch(klineUrl(INTERVAL, 2))).json();
						const klines = resp.result || [];
						if (!klines.length) return;
						const updated = toCandle(klines[0]);
						if (realCandles.length && realCandles[realCandles.length - 1].time === updated.time) {
							realCandles[realCandles.length - 1] = updated;
						} else {
							realCandles.push(updated);
						}
						rebuildSeriesData();
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
					}

					async function refreshDealerHedging() {
						showSpinner();
						try {
							const data = await (await fetch(dhsUrl())).json();
							lastData = data;
							renderOverlays(data);
							renderForecast(data);
							renderPanel(data);
							renderForecastBox(data);
							repositionRightBoxes();
							setStatus(ASSET + ' · Dealer Hedging Simulator · live');
						} catch (e) {
							setStatus('Error: ' + e.message);
						} finally {
							hideSpinner();
							nextRefreshAt = Date.now() + REFRESH;
							updateRefreshCountdown();
						}
					}

					let refreshTimer = null;
					function scheduleRefresh() {
						if (refreshTimer) clearTimeout(refreshTimer);
						nextRefreshAt = Date.now() + REFRESH;
						updateRefreshCountdown();
						refreshTimer = setTimeout(async () => { await refreshDealerHedging(); scheduleRefresh(); }, REFRESH);
					}
					function manualRefresh() { refreshDealerHedging().then(scheduleRefresh); }

					function updateRefreshCountdown() {
						const el = document.getElementById('refresh-countdown');
						if (!el) return;
						const secs = Math.round((nextRefreshAt - Date.now()) / 1000);
						if (secs <= 0) { el.textContent = 'refreshing…'; return; }
						const mm = String(Math.floor(secs / 60)).padStart(2, '0');
						const ss = String(secs % 60).padStart(2, '0');
						el.textContent = 'Next Update: ' + mm + ':' + ss;
					}

					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}
					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
					}

					function openHelpModal() { document.getElementById('help-modal').style.display = 'flex'; }
					function closeHelpModal() { document.getElementById('help-modal').style.display = 'none'; }

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];
					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}
					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					async function init() {
						try {
							await loadCandles();
							await refreshDealerHedging();
						} catch (e) { setStatus('Error: ' + e.message); }
						finally { scheduleRefresh(); }
					}
					init();
					updateRefreshCountdown();
					setInterval(updateLatestCandle, 5000);
					setInterval(updateRefreshCountdown, 1000);
				//
